const PRODIGI_PRESETS = [
  { id: "fine-art-print-a4", label: "A4 — 21 × 29.7 cm", sku: "GLOBAL-HGE-A4", sizing: "fillPrintArea", displayedSize: "21 × 29.7 cm" },
  { id: "fine-art-print-a3", label: "A3 — 29.7 × 42 cm", sku: "GLOBAL-HGE-A3", sizing: "fillPrintArea", displayedSize: "29.7 × 42 cm" },
  { id: "fine-art-print-a2", label: "A2 — 42 × 59.4 cm", sku: "GLOBAL-HGE-A2", sizing: "fillPrintArea", displayedSize: "42 × 59.4 cm" }
];
const SHIPPING_COUNTRIES = { BE: { name: "Belgium", rates: [680, 685, 690, 930] } };
const PACKAGING_GRAMS = { apparel: 300, prints: 500, paintings: 1000, sculptures: 1500, other: 500 };
const PACKAGING_PADDING_CM = { apparel: 0, prints: 6, paintings: 10, sculptures: 15, other: 6 };
const emptyCountryPrices = () => Object.fromEntries(Object.keys(SHIPPING_COUNTRIES).map(country => [country, ""]));
const euro = cents => cents == null ? "" : new Intl.NumberFormat("nl-BE", { style: "currency", currency: "EUR" }).format(cents / 100);
function shippingEstimate(items, country) { if (!SHIPPING_COUNTRIES[country]) return null; let weight = 0, packaging = 0, custom = 0; for (const item of items) { if ((item.shipping_mode || "automatic") === "custom") { const rate = Number(item.custom_shipping_prices?.[country]); if (!Number.isInteger(rate) || rate < 0) return null; custom += rate * item.quantity; } else { const grams = Number(item.shipping_weight_grams); if (!grams) return null; weight += grams * item.quantity; packaging = Math.max(packaging, PACKAGING_GRAMS[item.product_type] || PACKAGING_GRAMS.other); } } const rates = SHIPPING_COUNTRIES[country].rates; const packed = weight + packaging; const automatic = !weight ? 0 : packed <= 3000 ? rates[0] : packed <= 6000 ? rates[1] : packed <= 10000 ? rates[2] : Math.ceil(packed / 20000) * rates[3]; return automatic + custom; }
function purchasableStock(item) { return item.fulfillment_mode === "prodigi" ? item.stock_quantity == null ? 10 : Math.max(0, Number(item.stock_quantity)) : Math.max(0, Number(item.stock_quantity ?? 1)); }
function availabilityText(item, stock) { if (item.fulfillment_mode !== "prodigi") return stock === 0 ? "No longer available" : `${stock} ${stock === 1 ? "piece" : "pieces"} available`; return item.stock_quantity == null ? "Made to order" : stock === 0 ? "Sold out" : `Limited edition — ${stock} ${stock === 1 ? "piece" : "pieces"} available`; }
function prodigiPrintDetails(item) { if (item.fulfillment_mode !== "prodigi") return null; if (item.prodigi_sku?.startsWith("GLOBAL-HGE-")) return { name: "Hahnemühle German Etching", copy: "A heavyweight, softly textured fine-art paper with a warm natural-white tone and a velvety matte finish.", details: ["310 gsm fine-art paper", "Textured velvet-matte surface", "Museum-quality Giclée print", "Pigment inks for rich colour and long-lasting detail"] }; return null; }
function isStandardParcel(form) { if (!["paintings", "prints", "sculptures"].includes(form.productType)) return true; const padding = PACKAGING_PADDING_CM[form.productType] || 0; const packed = [form.shippingWidth, form.shippingHeight, form.shippingDepth].map(value => Number(value) + padding).sort((a, b) => b - a); return packed[0] <= 100 && packed[0] + 2 * (packed[1] + packed[2]) <= 250; }
function go(path) { history.pushState({}, "", path); dispatchEvent(new PopStateEvent("popstate")); scrollTo(0, 0); }
function Link({ to, children, className = "" }) { return <a href={to} className={className} onClick={event => { if (to.startsWith("/")) { event.preventDefault(); go(to); } }}>{children}</a>; }

