      {form.category === "shop" && <fieldset className="form-section"><legend>3. Shipping</legend>{form.fulfillmentMode === "prodigi" ? <p className="form-section-help">Prodigi calculates the live Standard shipping cost for Belgium when the customer opens their cart. No weight, package measurements or manual shipping price are needed.</p> : <><p className="form-section-help">Set the shipping amount charged for one of this item. It is added at checkout and is not calculated from weight or dimensions.</p><div className="form-section-grid">{Object.entries(SHIPPING_COUNTRIES).map(([country, details]) => <label key={country}>Shipping to {details.name} (€)<input inputMode="decimal" required value={form.customShippingPrices[country]} onChange={event => changeCountryPrice(country, event.target.value)} placeholder="0.00" /></label>)}</div></>}</fieldset>}
